// Üretilen dosya: tool/ozgun/uret.py. Tarih · Orta Asya Türk devletleri ve göçler (Hun, Göktürk, Uygur, Hazar, Avar) (kolay).
const ozHistory6Kolay = <(String, String, List<String>, String)>[
  ('Türklerin ilk ana yurdu olarak kabul edilen Orta Asya\'nın batı sınırını genel olarak hangi coğrafi unsurlar oluşturur?', 'Hazar Denizi ve Ural Dağları', ['Karadeniz ve Kafkas Dağları', 'Aral Gölü ile Seyhun Nehri\'nin aşağı havzası', 'Balkaş Gölü ve Tanrı Dağları'], 'Orta Asya ana yurdunun batı sınırı Hazar Denizi ile Ural Dağları olarak gösterilir. Doğuda Kingan Dağları, güneyde Hindukuş ve Tanrı Dağları sınırı tamamlar.'),
  ('Orta Asya\'nın büyük bölümünde karasal iklimin hüküm sürmesi, buradaki toplulukların geçim biçimini en çok hangi yönde etkilemiştir?', 'Otlak arayışına dayalı göçebe hayvancılığa yöneltmiştir', ['Sulama kanallarına dayalı yoğun tarım yapılan kalabalık kentler kurdurmuştur', 'Deniz ticaretini başlıca geçim kaynağı yapmıştır', 'Ormancılık ve kerestecilikte uzmanlaştırmıştır'], 'Yağışın az, kışların sert olduğu bozkırlar geniş tarıma uygun değildir; bu yüzden halk sürüleriyle mevsimlik otlaklar arasında dolaşarak hayvancılık yapmıştır.'),
  ('Orta Asya\'da kışlak ve yaylak arasında mevsimlik hareket eden bir obanın bu düzenli yer değiştirmesinin temel amacı nedir?', 'Hayvanlara yıl boyunca uygun otlak ve korunak sağlamak', ['Komşu boylardan vergi toplamak', 'Kervan yollarını denetim altında tutmak', 'Tarım ürünlerini farklı pazarlarda satmak'], 'Yazın serin ve otlu yaylalara çıkılır, kışın rüzgârdan korunaklı kışlaklara inilir. Bu döngü hayvancılığın sürdürülebilmesi içindir.'),
  ('Orta Asya\'dan dışarıya yapılan büyük göçlerin doğal nedenleri arasında aşağıdakilerden hangisi yer alır?', 'Kuraklık nedeniyle otlakların daralması', ['Kâğıdın icadıyla bürokrasinin büyümesi', 'Deniz yollarının keşfedilip kıyı ticaretinin hızla gelişmesi', 'Kalabalık kentlerde sanayinin gelişmesi'], 'Ders kitaplarında göçlerin doğal nedenleri olarak kuraklık, iklim değişikliği ve buna bağlı otlak yetersizliği sayılır.'),
  ('Bir boyun sürüleri bir salgın sonucu büyük ölçüde telef olmuş ve kalan otlaklar başka boylarca tutulmuştur. Bu boy için en olası sonuç aşağıdakilerden hangisidir?', 'Yeni otlaklar bulmak için başka bölgelere göç etmesi', ['Kalan hayvanları satıp denizciliğe yönelmesi', 'Kent kurup yalnız el sanatlarıyla geçinmesi', 'Göçebeliği bırakıp bulunduğu yerde pirinç tarımına yönelerek yerleşik hayata geçmesi'], 'Hayvancılığa dayalı bir toplulukta otlak ve sürü kaybı, geçimi sürdürebilmek için yeni yurt arayışına, yani göçe yol açar.'),
  ('Orta Asya\'dan batıya yapılan göçlerde Türk topluluklarının ulaştığı bölgeler arasında aşağıdakilerden hangisi yer alır?', 'Karadeniz\'in kuzeyi ve Doğu Avrupa', ['Arap Yarımadası\'nın güneyi', 'Japonya ve Kore yarımadası kıyıları', 'Avustralya kıyıları'], 'Batıya giden göç dalgaları Hazar\'ın kuzeyinden geçerek Karadeniz\'in kuzeyine, oradan Balkanlara ve Orta Avrupa\'ya ulaşmıştır.'),
  ('Batıya göç eden bazı Türk topluluklarının kendi dillerini ve kimliklerini zamanla kaybetmesinin en önemli nedeni aşağıdakilerden hangisidir?', 'Kalabalık yerli halklar arasında sayıca az kalıp onların dinini ve dilini benimsemeleri', ['Orta Asya\'daki akrabalarıyla yazışarak kendi kültürlerini canlı tutmaya çalışmaları', 'Göçebe yaşamı daha da yoğunlaştırmaları', 'Kendi alfabelerini geliştirip yaymaları'], 'Tuna Bulgarları gibi topluluklar Slav çoğunluk arasında az sayıda kalıp Hristiyanlığı ve Slav dilini benimseyince zamanla asimile olmuştur.'),
  ('Bozkır toplumlarında keçeden yapılan, kolayca sökülüp at ve deve sırtında taşınabilen konutlara genel olarak ne ad verilir?', 'Otağ ya da yurt', ['Kümbet', 'Kervansaray ve ribat', 'Taş kale'], 'Göçebe hayata uygun, keçe ile örtülü ahşap iskeletli çadırlar otağ (yurt) olarak anılır. Kümbet, kervansaray ve ribat taş yapılardır.'),
  ('Kısrak sütünün mayalandırılmasıyla elde edilen ve bozkır halklarının temel içeceklerinden biri olan ürün hangisidir?', 'Kımız', ['Şerbet', 'Boza', 'Ayran'], 'Kımız, kısrak sütünün mayalanmasıyla yapılan hafif ekşi ve hafif alkollü bir içecektir. Ayran inek ya da koyun sütü yoğurdundan, boza ise tahıldan yapılır.'),
  ('Atın evcilleştirilmesi ve binicilikte ustalaşılması, bozkır topluluklarına aşağıdakilerden hangisini en doğrudan kazandırmıştır?', 'Geniş alanlarda hızlı hareket ve savaşta üstünlük', ['Kalıcı taş kentler ve anıtsal saraylar kurma imkânı', 'Kalabalık bir köylü nüfusu', 'Deniz aşırı ticaret yolları'], 'At, göçebelere hem sürüleri geniş otlaklarda yönetme hem de atlı okçulukla savaşta hızlı manevra üstünlüğü sağlamıştır.'),
  ('Hayvancılıkla geçinen bozkır halklarının tahıl, kumaş ve ipek gibi ürünleri genellikle nasıl temin ettiği düşünülür?', 'Yerleşik komşularla ticaret yaparak ya da vergi ve haraç alarak', ['Kendi tarlalarında geniş ölçekte üreterek', 'Okyanus ötesinden ithal ederek', 'Yalnızca avcılıkla elde ettikleri kürkleri komşu boylarla takas ederek'], 'Bozkır ekonomisi bu ürünleri sınırlı ürettiğinden Çin gibi yerleşik komşularla at ve hayvan ürünleri karşılığında ticaret yapılmış, savaşla da haraç alınmıştır.'),
  ('Orta Asya\'da Türk topluluklarının ünlendiği el sanatları arasında, bozkırın hammaddesini doğrudan kullanan aşağıdakilerden hangisidir?', 'Yünden halı, kilim ve keçe yapımı', ['Mermerden heykel yontuculuğu', 'Papirüsten kâğıt üretimi', 'Fildişi ve değerli taşlardan oyma süs eşyası yapımı'], 'Koyun yünü bozkırın temel hammaddesidir; halı, kilim ve keçe bu nedenle Türk el sanatlarının en eski ve yaygın kollarındandır.'),
  ('Göçebe yaşam tarzının Türk sanatında \'taşınabilir sanat\' denilen eğilimi doğurmasının temel nedeni nedir?', 'Eşyaların sık yer değiştirme sırasında kolayca taşınmak zorunda olması', ['Dinî inançların büyük heykel ve resimleri yasaklaması', 'Bölgede taş ve mermer gibi yapı malzemelerinin hiç bulunmaması', 'Sanatçıların yalnız saraylarda çalışması'], 'Sürekli göç eden toplumlar sanatlarını kemer tokası, eyer, halı ve silah gibi taşınabilir eşyalar üzerinde geliştirmiştir.'),
  ('Orta Asya Türk sanatında hayvan figürlerinin çoğu zaman mücadele hâlinde ve stilize biçimde işlendiği süsleme anlayışına ne ad verilir?', 'Hayvan üslubu', ['Minyatür üslubu', 'Barok üslubu', 'Kübist üslup'], 'Hayvan üslubu, bozkır sanatında hayvanların birbirine saldırırken ya da kıvrılmış biçimde maden, ahşap ve deri eşyalara işlendiği süsleme tarzıdır.'),
  ('Bozkır toplumlarında madencilik ve demircilik bilgisinin önemli olmasının askerî açıdan en belirgin yararı neydi?', 'Silah, ok ucu ve at koşum takımlarını kendilerinin üretebilmesi', ['Büyük gemi filoları kurup uzak denizlerde sefer yapabilmeleri', 'Su kanalları açıp tarımı yaymaları', 'Taş kaleler inşa edebilmeleri'], 'Demir işçiliği atlı okçu ordusunun ihtiyaç duyduğu silah, zırh ve koşum takımlarının üretimini sağlamıştır.'),
  ('Bozkırda göçebe yaşayan Türk boylarının toplumsal yapısı en küçükten en büyüğe doğru nasıl sıralanır?', 'Aile – urug – boy – budun', ['Budun – boy – aile – urug', 'Urug – budun – aile – boy', 'Boy – aile – budun – urug'], 'Eski Türk toplumunda ailelerin birleşmesiyle urug, urugların birleşmesiyle boy, boyların birleşmesiyle budun (millet) oluşur.'),
  ('Eski Türklerde ailenin genel yapısı için aşağıdakilerden hangisi doğrudur?', 'Tek eşlilik yaygındı ve kadın toplumda saygın bir yere sahipti', ['Kadınların mülk edinmesi yasaktı', 'Aile yalnızca baba tarafından akrabalardan oluşan bir kabileydi', 'Çocuklar doğumdan itibaren devlete teslim edilirdi'], 'Kaynaklar eski Türklerde tek eşliliğin yaygın olduğunu ve kadının, özellikle hatunun, toplumsal ve siyasi hayatta saygın konumda bulunduğunu gösterir.'),
  ('Orta Asya\'nın ipek yollarının üzerinde bulunması, buradaki Türk devletleri için hangi fırsatı yaratmıştır?', 'Ticaretten vergi ve gümrük geliri elde etmeyi', ['Okyanus limanları kurmayı', 'Avrupa\'dan tahıl ithal etmeyi', 'Deniz yoluyla uzak ülkelerle balık ticareti yapmayı'], 'Çin ile Batı arasındaki kervan yollarını denetleyen Türk devletleri, geçen ticaretten vergi alarak ve aracılık yaparak gelir sağlamıştır.'),
  ('Orta Asya\'dan güneye yönelen göçlerle Türk toplulukları başlıca hangi bölgelere ulaşmıştır?', 'Afganistan ve Hindistan\'ın kuzeyi', ['İskandinavya ve Baltık Denizi kıyıları', 'Kuzey Afrika kıyıları', 'Japonya'], 'Güney yönündeki göçlerle Ak Hunlar gibi topluluklar Toharistan, Afganistan ve Kuzey Hindistan\'a yayılmıştır.'),
  ('Asya Hun Devleti\'nin bilinen ilk hükümdarı olarak kaynaklarda adı geçen kişi kimdir?', 'Teoman (Tuman)', ['Çiçi (Zhizhi)', 'Ki-ok (Lao-şang)', 'Huhanye'], 'Çin kaynaklarında adı geçen ilk Hun hükümdarı Teoman\'dır; Mete onun oğludur ve babasının yerine geçmiştir.'),
  ('Çin kaynaklarına göre Mete\'nin askerlerine sadakat ve disiplin kazandırmak için kullandığı, attığı yöne herkesin ok atmasını istediği özel ok hangisidir?', 'Islıklı (vızıldayan) ok', ['Zehirli ok', 'Ateşli ok', 'Çift uçlu kemik ok'], 'Mete, ıslıklı okunu hangi hedefe atarsa askerlerinin de aynı hedefe atmasını emretmiş ve itaatsizleri cezalandırarak mutlak bir disiplin kurmuştur.'),
  ('Mete\'nin orduyu onluk, yüzlük, binlik ve on binlik birliklere ayırmasının devlet ve ordu açısından en önemli yararı nedir?', 'Emir-komuta zincirini kolaylaştırıp hızlı ve düzenli hareket sağlaması', ['Askerlerin kendi komutanlarını kurultayda seçmesine olanak tanıyıp yetkiyi dağıtması', 'Orduyu yalnız piyadelerden oluşturması', 'Askerlik hizmetini isteğe bağlı hâle getirmesi'], 'Onlu sistem birlikleri hiyerarşik bir yapıya kavuşturur; komutanlar küçük birimlerden büyüğe doğru sorumludur ve ordu hızla yönetilir.'),
  ('Mete\'nin kurduğu onlu sistemin ilkesi, bugün pek çok ülkenin kara kuvvetlerindeki hangi uygulamada izini sürdürür?', 'Takım, bölük, tabur gibi kademeli birlik yapısında', ['Askerî üniformaların renginde', 'Asker maaşlarının hesaplanmasında', 'Ordunun yalnızca gönüllülerden ve paralı askerlerden oluşturulmasında'], 'Birliklerin küçükten büyüğe kademeli olarak düzenlenmesi ilkesi, modern ordulardaki takım-bölük-tabur yapısına benzetilir; Türk Kara Kuvvetleri kuruluş yılını da MÖ 209\'a dayandırır.'),
  ('Türk Kara Kuvvetleri kuruluş tarihini hangi olaya dayandırır?', 'Mete\'nin MÖ 209\'da tahta çıkıp orduyu düzenlemesine', ['Attila\'nın 451 Katalon Savaşı\'na', 'Bumin Kağan\'ın 552\'de Juan-juan egemenliğine son vermesine', 'Talas Savaşı\'na'], 'Türk Kara Kuvvetleri, Mete\'nin MÖ 209\'da Hun tahtına çıkışını ve onlu sistemle düzenli orduyu kurmasını kuruluş tarihi kabul eder.'),
  ('Mete\'nin doğudaki komşularından kendisine ait \'en iyi atı\' ve \'hatununu\' istediklerinde verip, toprak istediklerinde savaş açtığı topluluk hangisidir?', 'Tunguzlar (Tung-hu)', ['Yüeçiler (Yuezhi)', 'Çinliler', 'Wusunlar'], 'Rivayete göre Mete, Tunguzların at ve hatun isteklerini kabul etmiş, fakat toprak istediklerinde \'Toprak devletin temelidir\' diyerek saldırmış ve onları yenmiştir.'),
  ('Çin imparatoruna yazdığı mektupta Orta Asya\'daki yirmi altı kavmi kendi egemenliğine aldığını bildiren Hun hükümdarı kimdir?', 'Mete', ['Teoman', 'Ki-ok', 'Çiçi'], 'Mete, MÖ 176\'da Çin imparatoruna gönderdiği mektupta Yüeçileri yendiğini ve yirmi altı kavmi Hun idaresinde birleştirdiğini bildirmiştir.'),
  ('Çin Seddi\'nin büyük ölçüde birleştirilip genişletilmesinin temel amacı aşağıdakilerden hangisiydi?', 'Kuzeydeki göçebe atlı toplulukların, özellikle Hunların akınlarını durdurmak', ['Sarı Irmak taşkınlarını önlemek', 'Doğu kıyılarındaki limanları deniz korsanlarına karşı korumak', 'Çin\'in iç bölgelerinde vergi toplamak'], 'Çin Seddi, Qin ve Han dönemlerinde kuzeyden gelen göçebe akınlarına karşı savunma hattı olarak birleştirilip güçlendirilmiştir.'),
  ('Asya Hun Devleti\'nin yönetim merkezi olarak kabul edilen ve sonraki Türk devletlerince de kutsal sayılan bölge hangisidir?', 'Ötüken', ['Balasagun', 'Semerkant', 'Kaşgar'], 'Ötüken, Orhun ve Selenga ırmakları çevresindeki ormanlık-dağlık bölgedir; Hunlardan sonra Göktürkler ve Uygurlar da burayı merkez edinmiştir.'),
  ('Avrupa Hunları İdil (Volga) Nehri\'ni geçerek Karadeniz\'in kuzeyine hangi hükümdarın önderliğinde gelmiştir?', 'Balamir', ['Rua', 'Attila', 'Uldız'], '375 yılında Balamir önderliğindeki Hunlar İdil\'i geçmiş, Alanları ve ardından Ostrogotları yenerek batıya ilerlemiştir.'),
  ('Hunların Ostrogotları yenmesinin ardından Vizigotların Roma topraklarına sığınmak istemesi hangi zincirleme sürecin başlangıcı sayılır?', 'Kavimler Göçü', ['Haçlı Seferleri', 'Reconquista', 'Viking akınları'], 'Hun baskısıyla yerinden oynayan Got ve diğer Germen kavimlerinin Roma sınırlarını aşması, 375\'te başlayan Kavimler Göçü olarak adlandırılır.'),
  ('Rua\'nın ölümünden sonra 434\'te Avrupa Hun tahtına birlikte geçen kardeşler kimlerdir?', 'Attila ve Bleda', ['Basık ve Kursık', 'İlek ve İrnek', 'Balamir ve Uldız'], 'Rua\'nın yeğenleri Attila ve Bleda devleti ortak yönetmiş; Bleda\'nın 445 dolaylarında ölümüyle Attila tek hükümdar olmuştur.'),
  ('Margus Antlaşması\'nda Bizans\'ın sınırda Hun tüccarlarına pazar yerleri açmayı kabul etmesi Hunlara hangi alanda doğrudan kazanç sağlamıştır?', 'Ticaret', ['Denizcilik', 'Mimari', 'Din eğitimi'], 'Sınır pazarları, Hunların ürünlerini satıp Bizans mallarını serbestçe alabilmesini sağlayarak ekonomik çıkar yaratmıştır.'),
  ('451\'de Attila komutasındaki Hun ordusu ile Romalı komutan Aetius\'un önderliğindeki Roma-Germen ordusu arasında Galya\'da yapılan savaş hangisidir?', 'Katalon Ovası Savaşı', ['Edirne (Hadrianopolis) Savaşı', 'Nedao Savaşı', 'Kadeş Savaşı'], '451\'deki Katalon (Catalaunum) Savaşı kesin bir sonuç vermemiş, Attila geri çekilerek ertesi yıl İtalya\'ya yönelmiştir.'),
  ('Avrupa Hunlarının Avrupa tarihine etkileri arasında aşağıdakilerden hangisi gösterilemez?', 'Avrupa\'da Hristiyanlığın ortaya çıkması', ['Kavimler Göçü\'nü tetiklemeleri', 'Batı Roma\'nın zayıflamasına katkıda bulunmaları', 'Bizans\'ı uzun süre vergiye bağlamaları'], 'Hristiyanlık Hunlardan yüzyıllar önce ortaya çıkmıştır; diğer seçenekler Hunların bilinen etkileridir.'),
  ('Göktürk Devleti\'nin Türk tarihi açısından ayırt edici özelliklerinden biri aşağıdakilerden hangisidir?', 'Türk adını resmî devlet adı olarak kullanan ilk devlet olması', ['Türk tarihindeki ilk düzenli orduyu onlu sisteme göre kuran devlet olması', 'İslamiyet\'i resmî din olarak kabul eden ilk Türk devleti olması', 'Yerleşik hayata tümüyle geçerek kentlerde yaşayan ilk Türk devleti olması'], 'Göktürkler \'Türk\' adını devletin resmî adı olarak kullanan ilk devlettir. Onlu sistem Hunlara, İslamiyet Karahanlılara, yerleşik hayat Uygurlara bağlanır.'),
  ('Bumin\'in ölümünden sonra Göktürk Devleti\'nin batı kanadını yöneten ve \'Yabgu\' unvanını taşıyan kardeşi kimdir?', 'İstemi', ['Mukan', 'Taspar', 'Tardu'], 'Bumin doğu kanadının kağanı iken kardeşi İstemi batı kanadını Yabgu unvanıyla yönetmiş, batıya doğru geniş fetihler yapmıştır.'),
  ('Doğu Göktürk Devleti 630\'da hangi Çin hanedanının egemenliğine girmiştir?', 'Tang hanedanı', ['Han hanedanı', 'Ming hanedanı', 'Qin hanedanı'], 'Doğu Göktürkleri 630\'da Tang hanedanına yenilmiş; kağanları esir alınmış ve yaklaşık yarım yüzyıl sürecek Çin egemenliği başlamıştır.'),
  ('Göktürklerin 630–681 arasında Çin egemenliğinde geçirdiği döneme Türk tarihinde genellikle hangi ad verilir?', 'Fetret (esaret) dönemi', ['Lale Devri', 'Kavimler Göçü ve dağılma dönemi', 'Duraklama devri'], 'Bağımsızlığın kaybedildiği bu yaklaşık elli yıllık süre Türk tarihinde fetret ya da esaret dönemi olarak anılır.'),
  ('639\'da kırk yiğidiyle birlikte Çin imparatorunun sarayına baskın düzenleyen ve bu girişimi bağımsızlık mücadelesinin sembolü sayılan Göktürk prensi kimdir?', 'Kürşad', ['Kül Tigin', 'Tonyukuk', 'Yolluğ Tigin'], 'Kürşad, kırk arkadaşıyla Tang sarayına baskın yapmış; başarısız olup hayatını kaybetse de bağımsızlık ruhunun simgesi olmuştur.'),
  ('Kül Tigin yazıtında fetret dönemi için söylenen \'Bey olacak oğlun kul oldu, hanım olacak kızın cariye oldu\' sözü neyi vurgulamaktadır?', 'Bağımsızlığın yitirilmesiyle Türk toplumunun Çin\'e tutsak düşmesini', ['Türk toplumunda köleliğin olağan ve yaygın bir kurum hâline geldiğini', 'Çin ile kurulan evlilik bağlarının yararını', 'Kadınların siyasi hayattan dışlandığını'], 'Yazıt, Türk beylerinin Çin\'e bağlanıp unvanlarını yitirdiği, halkın da tutsak duruma düştüğü acı dönemi bu sözlerle anlatır.'),
  ('Orhun yazıtlarına göre fetret döneminde Türk beylerinin yaptığı ve yazıtta sitemle anılan davranış hangisidir?', 'Türk unvanlarını bırakıp Çin unvanlarını alarak Çin kağanına bağlanmaları', ['Göç ederek Avrupa\'ya gitmeleri ve orada yeni bir devlet kurmaları', 'Hep birlikte Budizmi kabul edip manastırlara çekilerek devlet işlerinden tümüyle el çekmeleri', 'Ticareti bırakıp tümüyle tarıma yönelerek köylü olmaları'], 'Yazıtlar, Türk beylerinin Çin unvanları alarak Çin kağanına hizmet ettiğini ve Türk halkının bu yüzden kendi devletini yitirdiğini anlatır.'),
  ('II. Göktürk (Kutluk) Devleti\'ni 681\'de Çin\'e karşı ayaklanarak kuran hükümdar kimdir?', 'İlteriş Kutluk Kağan', ['Bilge Kağan', 'Kapgan Kağan', 'Bumin Kağan'], 'Kutluk, Çin egemenliğine karşı ayaklanmış, devleti yeniden kurduktan sonra \'İlteriş\' (ili derleyen) unvanını almıştır.'),
  ('İlteriş Kutluk Kağan\'ın devleti yeniden kurmasında en büyük destekçisi olan ve sonraki iki kağana da danışmanlık yapan devlet adamı kimdir?', 'Tonyukuk', ['Kürşad', 'Yolluğ Tigin', 'Moyun Çor'], 'Tonyukuk; İlteriş, Kapgan ve Bilge Kağan dönemlerinde vezirlik ve başkomutanlık yapmış, II. Göktürk Devleti\'nin kurucu aklı sayılmıştır.'),
  ('Kapgan Kağan\'ın ölümünden sonra tahta, kardeşi Kül Tigin\'in desteğiyle geçen hükümdar kimdir?', 'Bilge Kağan', ['İlteriş Kutluk Kağan', 'Özmış Kağan', 'Kutluk Bilge Kül Kağan'], 'Kapgan\'ın oğulları tahta geçmek isteyince Kül Tigin onları ortadan kaldırmış ve ağabeyi Bilge Kağan\'ı 716\'da tahta çıkarmıştır.'),
  ('Orhun yazıtları olarak bilinen üç büyük anıt yazıt hangi kişiler adına dikilmiştir?', 'Kül Tigin, Bilge Kağan ve Tonyukuk', ['Bumin, İstemi ve Mukan Kağan', 'Mete, Teoman ve Ki-ok', 'Bögü Kağan, Moyun Çor ve Kutluk Bilge Kül Kağan'], 'Orhun yazıtları II. Göktürk dönemine aittir ve Kül Tigin, Bilge Kağan ile Tonyukuk adına dikilmiştir.'),
  ('Kül Tigin ve Bilge Kağan yazıtlarının metnini yazdığı, yazıtlarda kendisinin de adının geçtiği kişi kimdir?', 'Yolluğ Tigin', ['Tonyukuk', 'Kürşad', 'Kaşgarlı Mahmut'], 'Yazıtların sonunda metni yazanın Bilge Kağan\'ın yeğeni Yolluğ Tigin olduğu belirtilir.'),
  ('Göktürk yazıtlarını 1893\'te çözerek okunabilir hâle getiren Danimarkalı dil bilimci kimdir?', 'Vilhelm Thomsen', ['Wilhelm Radloff', 'Nikolay Yadrintsev', 'Philip Johan von Strahlenberg'], 'Vilhelm Thomsen 1893\'te Göktürk alfabesini çözdüğünü duyurmuş; ilk okuduğu sözcükler arasında \'Tengri\' ve \'Türk\' yer almıştır.'),
  ('Kül Tigin yazıtının bir yüzünde Türkçe metnin yanında başka bir dilde de yazı bulunur. Bu dil hangisidir?', 'Çince', ['Soğdca', 'Farsça', 'Grekçe'], 'Kül Tigin yazıtının bir yüzünde Tang imparatorunun gönderdiği Çince bir metin yer alır; bu da iki devlet arasındaki ilişkiyi gösterir.'),
  ('Kül Tigin ve Bilge Kağan yazıtlarının bulunduğu ülke bugün hangisidir?', 'Moğolistan', ['Kazakistan', 'Kırgızistan', 'Türkmenistan'], 'Yazıtlar Moğolistan\'da Orhun Irmağı vadisinde, Koşo Tsaydam denilen yerde bulunur.'),
  ('Kül Tigin yazıtı 732\'de, Bilge Kağan yazıtı 735\'te dikilmiştir. Bilge Kağan yazıtı ile 1893\'te Thomsen\'in yazıyı çözmesi arasında kaç yıl vardır?', '1158', ['1161', '1148', '1258'], '1893 − 735 = 1158 yıl. Kül Tigin yazıtı esas alınsaydı fark 1161 olurdu.'),
  ('\'Ey Türk milleti! Üstte gök çökmedikçe, altta yer delinmedikçe senin ilini ve töreni kim bozabilir?\' sözü hangi yazıtta yer alır?', 'Kül Tigin yazıtında', ['Tonyukuk yazıtında', 'Şine Usu yazıtında', 'Yenisey yazıtlarında'], 'Bu ünlü ifade Kül Tigin yazıtında geçer ve Türk milletinin birliğini koruduğu sürece yıkılmayacağını vurgular.'),
  ('\'Ey Türk milleti! Üstte gök çökmedikçe, altta yer delinmedikçe senin ilini ve töreni kim bozabilir?\' ifadesinde öne çıkarılan düşünce aşağıdakilerden hangisidir?', 'Milletin birlik ve törelerine bağlı kaldıkça devletin yıkılmayacağı', ['Gök ile yerin bir gün mutlaka yok olacağı ve dünyanın sona ereceği inancı', 'Türklerin yalnız gökyüzündeki tanrılara tapması gerektiği', 'Devletin sınırlarının yer ve gök kadar geniş olduğu'], 'Söz, devleti ayakta tutan şeyin milletin birliği ve töreye bağlılığı olduğunu, bunlar korundukça hiçbir gücün ili bozamayacağını anlatır.'),
  ('Bilge Kağan\'ın \'Aç milleti doyurdum, çıplak milleti giydirdim, az milleti çok kıldım\' sözleri, eski Türklerde hükümdarın hangi sorumluluğuna işaret eder?', 'Halkın refahını ve çoğalmasını sağlama görevine', ['Yalnızca savaş kazanıp ganimet toplama görevine', 'Dinî törenleri yönetme ve kurban sunma görevine', 'Saray için gösterişli yapılar inşa etme görevine'], 'Bu ifadeler, kağanın meşruiyetinin halkı doyurmak, giydirmek ve çoğaltmak gibi toplumsal sorumluluklara bağlı olduğunu gösterir.'),
  ('Orhun yazıtlarında Türk milletine \'Ötüken ormanında oturursan ebedî il tutarsın\' denilerek hangi öğüt verilir?', 'Türk yurdunun merkezinde kalarak Çin\'e yaklaşmamak', ['Ormanları kesip yerine geniş tarım alanları açarak yerleşik hayata geçmek', 'Batıya göç ederek yeni yurt aramak', 'Ötüken\'i Çin\'e bırakıp güneye inmek'], 'Yazıtlar, Ötüken\'de kalan Türklerin devletini koruyacağını, Çin topraklarına yaklaşanların ise öleceğini belirterek yurda bağlılığı öğütler.'),
  ('Göktürk alfabesi ile yazılmış metinlerin yazılış yönü genellikle hangisidir?', 'Sağdan sola', ['Soldan sağa', 'Yukarıdan aşağıya ve sağdan sola sütunlar hâlinde', 'Bir satır soldan sağa, bir satır sağdan sola'], 'Göktürk harfleriyle yazılan metinler genel olarak sağdan sola yazılır; yazıtlarda satırlar yatay ya da dikey düzenlenebilir.'),
  ('Uygurlarda Maniheizmi devlet dini olarak kabul eden hükümdar kimdir?', 'Bögü Kağan', ['Moyun Çor', 'Kutluk Bilge Kül Kağan', 'Barçuk Art Tigin'], 'Bögü Kağan, An Lu-şan İsyanı sırasında Loyang\'da tanıştığı Mani rahiplerini yanında götürmüş ve 762\'den sonra Maniheizmi devlet dini yapmıştır.'),
  ('Uygurların Soğd yazısından geliştirdiği ve sonraki yüzyıllarda Moğolların da benimsediği yazı sistemi hangisidir?', 'Uygur alfabesi', ['Göktürk alfabesi', 'Kiril alfabesi', 'Arap alfabesi'], 'Soğd kökenli Uygur alfabesi Orta Asya\'da yaygınlaşmış; 13. yüzyılda Moğolların yazısı da bu alfabeden türemiştir.'),
  ('Uygur Kağanlığı 840\'ta hangi Türk topluluğunun saldırısıyla yıkılmıştır?', 'Kırgızlar', ['Karluklar', 'Basmiller', 'Türgişler'], 'İç karışıklıklar, kıtlık ve salgınla zayıflayan Uygur Kağanlığı 840\'ta Kırgızların saldırısıyla yıkılmıştır.'),
  ('840\'tan sonra Uygurların göç ettiği ve küçük devletler kurduğu iki bölge aşağıdakilerden hangisinde birlikte verilmiştir?', 'Kansu ve Turfan', ['Kırım ve Kafkasya', 'Horasan ve Azerbaycan', 'Pannonia ve Trakya'], 'Yıkılıştan sonra Uygurların bir kısmı Kansu\'ya, bir kısmı Doğu Türkistan\'daki Turfan bölgesine giderek buralarda yeni devletler kurmuştur.'),
  ('Kırgızlar, Uygur Kağanlığı\'nı yıkmadan önce yüzyıllar boyunca hangi ırmak havzasında yaşamışlardır?', 'Yenisey', ['Tuna (Danube) havzası', 'Fırat', 'İndus'], 'Kırgızların ana yurdu Güney Sibirya\'daki Yenisey havzasıdır; Yenisey yazıtları da bu bölgede bulunur.'),
  ('Avrupa Avar Kağanlığı\'nın en güçlü hükümdarı ve kurucusu olarak kabul edilen kağan kimdir?', 'Bayan Kağan', ['Attila', 'Kubrat', 'Krum Han'], 'Bayan Kağan (562–602) Avarları Macaristan ovasına yerleştirmiş ve Bizans\'ı vergiye bağlayan güçlü bir devlet kurmuştur.'),
  ('Üzenginin süvarilere sağladığı temel avantaj aşağıdakilerden hangisidir?', 'At üzerinde dengeyi artırıp ok atma ve mızrak kullanmayı kolaylaştırması', ['Atın daha az yemle beslenmesini sağlaması', 'Süvariyi oklara karşı tamamen koruması', 'Atın yük taşıma kapasitesini iki katına çıkarıp uzun yolculukları kısaltması'], 'Üzengi binicinin ayaklarını sabitleyerek dengeyi artırır; bu sayede süvari at üstünde ok atarken ve mızrakla saldırırken daha güçlü olur.'),
  ('Hazar Kağanlığı\'nın yönetici sınıfının 8.–9. yüzyıllarda benimsediği din hangisidir?', 'Musevilik', ['Maniheizm', 'Budizm', 'Zerdüştlük'], 'Hazar kağanı ve yönetici çevreler Museviliği benimsemiş; halk arasında ise Müslüman, Hristiyan ve eski inançlara bağlı topluluklar yaşamayı sürdürmüştür.'),
  ('Bugün dünyanın en büyük gölü olan ve Türkçede adını bir Türk devletinden alan su kütlesi hangisidir?', 'Hazar Denizi', ['Aral Gölü', 'Balkaş Gölü', 'Baykal Gölü'], 'Hazar Denizi, kıyılarında uzun süre egemen olan Hazar Kağanlığı\'ndan dolayı bu adla anılır.'),
  ('Kubrat Han\'ın oğullarından Asparuh\'un önderliğindeki Bulgarların yerleşip devlet kurduğu bölge aşağıdakilerden hangisidir?', 'Tuna\'nın güneyi', ['İdil ve Kama ırmaklarının birleştiği yer', 'Macaristan ovasının batısı ve Tuna\'nın kuzeyindeki bataklık bölgeler', 'Kırım\'ın güney kıyıları'], 'Asparuh Tuna\'yı geçmiş ve 681\'de Bizans\'a kendini tanıtarak Tuna Bulgar Devleti\'ni kurmuştur. İdil-Kama bölgesine giden kol ise İdil Bulgarlarını oluşturmuştur.'),
  ('Kıpçakların 11. yüzyıldan itibaren hâkim olduğu, Karadeniz\'in kuzeyinden Hazar\'ın doğusuna uzanan geniş bozkırlara İslam kaynaklarında verilen ad nedir?', 'Deşt-i Kıpçak', ['Maveraünnehir', 'Pannonia', 'Toharistan'], 'Kıpçakların egemenliğindeki bu bozkırlar İslam kaynaklarında \'Kıpçak bozkırı\' anlamına gelen Deşt-i Kıpçak adıyla anılmıştır.'),
  ('Eski Türklerde hükümdara yönetme yetkisinin Gök Tanrı tarafından verildiğine inanılan bu güce ne ad verilir?', 'Kut', ['Töre', 'Toy', 'Yargu'], 'Kut, hükümdarın yönetme hakkını Tanrı\'dan aldığı inancını ifade eder. Töre hukuk kuralları, toy meclis, yargu ise mahkemedir.'),
  ('Eski Türk inancına göre halkını açlık ve zulüm içinde bırakan, savaşlarda sürekli yenilen bir hükümdar için ne düşünülürdü?', 'Kutunun elinden alınmış olabileceği', ['Kutunun daha da güçlendiği ve Tanrı\'nın onu sınadığı', 'Töreye karşı bir yetkisinin doğduğu', 'Kurultayın artık toplanmayacağı'], 'Kut kalıcı değildi; başarısız ve adaletsiz hükümdarın Tanrı\'nın verdiği kutu kaybettiğine inanılır, bu da isyanlara meşruiyet kazandırırdı.'),
  ('Eski Türklerde yazılı olmayan, gelenek ve görenekler ile kağanın koyduğu kurallardan oluşan hukuk düzenine ne ad verilir?', 'Töre', ['Kut', 'Tamga', 'Balbal'], 'Töre, Türk devletlerinde toplumu ve devleti düzenleyen yazısız hukuk kurallarının bütünüdür.'),
  ('Bir Göktürk kağanı ihtiyaç doğduğunda yeni bir kural koymak istiyor. Eski Türk geleneğine göre bu kuralın yerleşmesi için en uygun yol hangisidir?', 'Kuralı kurultayda beylerle görüşerek kabul ettirmek', ['Kuralı yalnızca Çin imparatoruna onaylatmak', 'Kuralı kamların kehanetine ve gök işaretlerine bırakmak', 'Kuralı halk arasında kura çekerek belirlemek'], 'Kağan yeni töre koyabilirdi; ancak önemli kararlar kurultayda beylerin görüşü alınarak benimsenirdi.'),
  ('Eski Türklerde devlet işlerinin görüşüldüğü ve \'toy\' ya da \'kengeş\' adlarıyla da anılan meclis hangisidir?', 'Kurultay', ['Divan-ı Hümayun', 'Senato', 'Meclis-i Mebusan'], 'Kurultay; kağan, hatun, beyler ve boy liderlerinin katıldığı, savaş, barış ve töre gibi konuların görüşüldüğü danışma meclisidir.'),
  ('Kurultayın eski Türk devlet yapısındaki işleviyle ilgili aşağıdakilerden hangisi doğrudur?', 'Danışma niteliğindeydi; son kararı genellikle kağan verirdi', ['Kağanı her yıl seçimle değiştiren ve yasaları tek başına yapan bir parlamentoydu', 'Yalnızca dinî törenlerin yapıldığı bir tapınaktı', 'Halkın tamamının oy kullandığı bir seçim kuruluydu'], 'Kurultay bir danışma meclisiydi; görüşler alınır, ancak nihai karar çoğunlukla kağana ait olurdu.'),
  ('Eski Türk devletlerinde bazı emirlerin \'Kağan ve Hatun buyurur ki\' ifadesiyle başlaması neyi gösterir?', 'Hatunun devlet yönetiminde resmî bir yere sahip olduğunu', ['Hatunun yalnız saray mutfağından sorumlu olduğunu', 'Kağanın okuma yazma bilmediğini ve emirleri hatunun yazdığını', 'Emirlerin halk tarafından yazıldığını'], 'Hatunun adının fermanlarda kağanla birlikte geçmesi, kadının devlet yönetiminde saygın ve resmî bir konuma sahip olduğunu gösterir.'),
  ('Eski Türk devletlerinde ülkenin doğu ve batı olarak iki kanada ayrılıp doğuda kağanın, batıda yabgunun yönetmesi hangi uygulamadır?', 'İkili teşkilat', ['Onlu sistem', 'İkta sistemi', 'Tımar sistemi'], 'İkili teşkilatta doğu kanadı üstün sayılır, kağan burada bulunur; batı kanadı ise kağana bağlı yabgu tarafından yönetilir.'),
  ('İkili teşkilatın Türk devletlerine sağladığı en önemli yarar aşağıdakilerden hangisidir?', 'Geniş toprakların daha kolay yönetilip savunulması', ['Devletin hiçbir zaman bölünmemesi', 'Taht kavgalarının tümüyle ortadan kalkması', 'Göçebe hayatın sona ermesi'], 'Bozkırdaki geniş alanlar iki merkezden yönetilerek denetim ve savunma kolaylaşmıştır.'),
  ('Eski Türk devletlerinde ordunun \'ordu-millet\' niteliği taşıdığı söylenir. Bunun anlamı nedir?', 'Savaşabilecek yaştaki bütün erkeklerin asker sayılması', ['Ordunun yalnız para karşılığı savaşan profesyonellerden oluşması', 'Askerlerin yalnızca yabancı halklardan seçilmesi', 'Ordunun yalnız saray muhafızlarından oluşması'], 'Göçebe toplumda her erkek küçük yaştan binicilik ve okçuluk öğrenir; savaş zamanında bütün millet ordu hâline gelirdi.'),
  ('Bozkır atlı okçularının kullandığı, ahşabın yanına boynuz ve hayvan siniri katılarak yapılan, kısa ama çok güçlü yay türüne ne ad verilir?', 'Bileşik (kompozit) yay', ['Uzun yay', 'Arbalet', 'Mancınık'], 'Bileşik yay, farklı malzemelerin birleştirilmesiyle yapılır; kısa olduğu için at üstünde kolay kullanılır ve uzun menzile sahiptir.'),
  ('Eski Türklerde büyük sürek avlarının (sığır) devlet açısından taşıdığı önem aşağıdakilerden hangisidir?', 'Orduyu barış zamanında savaşa hazır tutan bir tatbikat işlevi görmesi', ['Ülkedeki yabani hayvanların tamamen yok edilmesini amaçlaması', 'Yalnızca saraydaki kadınların eğlencesi için düzenlenmesi', 'Çin\'e ihraç edilecek kürkleri toplamanın tek yolu olması'], 'Binlerce atlının katıldığı sürek avları, birliklerin uyum içinde kuşatma yapmasını öğreten bir askerî eğitim niteliği taşırdı.'),
  ('Eski Türkçede \'ordu\' sözcüğünün askerî birlik anlamının yanında taşıdığı bir diğer anlam aşağıdakilerden hangisidir?', 'Hükümdarın oturduğu karargâh ve saray', ['Kutsal dağ ve orman', 'Ölünün gömüldüğü mezar ve kurgan alanı', 'Ticaret kervanı'], '\'Ordu\' eski Türkçede hükümdarın otağının bulunduğu merkezi, sarayı da ifade eder; Uygur başkenti Ordu-Balık\'ın adı bu anlamla ilgilidir.'),
  ('Bozkır ordularının yerleşik devletlerin piyade ağırlıklı ordularına karşı genellikle üstün olmasının başlıca nedeni aşağıdakilerden hangisidir?', 'Hız, manevra yeteneği ve uzaktan ok atabilen atlı birlikler', ['Ağır kuşatma makinelerini her savaşta taşımaları', 'Kalabalık bir deniz filosuna sahip olup kıyılardan çıkarma yapmaları', 'Yalnızca surlu kentlerde savunma savaşı yapmaları'], 'Atlı okçular düşmana yaklaşmadan ok yağdırıp hızla yer değiştirebildiğinden ağır ve yavaş piyade ordularına karşı avantaj sağlardı.'),
  ('Eski Türk inancında evrenin yaratıcısı ve en yüce varlık olarak kabul edilen güç aşağıdakilerden hangisidir?', 'Gök Tanrı', ['Erlik', 'Umay', 'Yer-Su'], 'Gök Tanrı en yüce varlıktır; Erlik kötülüğün ve yeraltının, Umay kadın ve çocukların koruyucusudur, Yer-Su ise kutsal sayılan yer ve sulardır.'),
  ('Eski Türk inanç sisteminde yeraltı dünyasının hâkimi ve kötülüklerin kaynağı olarak görülen varlık hangisidir?', 'Erlik', ['Umay', 'Gök Tanrı', 'Ay Ata'], 'Erlik, eski Türk ve Altay inançlarında yeraltında yaşayan, ölüleri ve kötü ruhları yöneten varlıktır.'),
  ('Orhun yazıtlarında \'kutsal Yer-Su\' ifadesinin geçmesi eski Türklerin hangi inancını gösterir?', 'Doğadaki dağ, ırmak ve toprağın kutsal ruhlarca korunduğuna inanılmasını', ['Denizlerin tek tanrı olarak kabul edilmesini', 'Yeryüzünün ve suların kötülüklerin kaynağı sayılıp lanetlendiğini', 'Ölülerin suya gömülmesini'], 'Yer-Su, yurdu koruyan kutsal yer ve su ruhlarını ifade eder; tabiatın kutsallığına dayanan bir inancı yansıtır.'),
  ('Eski Türklerde insanlar ile ruhlar arasında aracılık yaptığına inanılan, hastaları iyileştirmeye ve törenleri yönetmeye çalışan kişiye ne ad verilirdi?', 'Kam', ['Tudun', 'Bitikçi', 'Ayguçı'], 'Kam (Batı kaynaklarında şaman), ruhlarla iletişim kurduğuna inanılan, ayin ve iyileştirme işlerini yürüten kişidir.'),
  ('Eski Türklerde ölünün ardından yapılan, ağıtların yakıldığı ve yemek verildiği cenaze törenine ne ad verilirdi?', 'Yuğ', ['Toy', 'Sığır', 'Kurultay'], 'Yuğ, ölen kişi için düzenlenen yas ve cenaze törenidir; bu törende ağıtlar (sagu) söylenirdi.'),
  ('Hun ve Göktürk kaynaklarında yas tutan kişilerin saçlarını kesmesi ve yüzlerini bıçakla çizmesi hangi duyguyu ifade etmek amacıyla yapılırdı?', 'Ölen kişiye duyulan derin acı ve bağlılık', ['Düşmana karşı savaş ilanı', 'Yeni kağanın tahta çıkışını kutlama ve ona bağlılık bildirme', 'Bayram sevincini paylaşma'], 'Bu yas gelenekleri ölenin ardından duyulan büyük acıyı ve ona saygıyı göstermek için yapılırdı; Attila\'nın ölümünde de benzer bir yas anlatılır.'),
  ('Kurganlara ölünün atı, silahları ve günlük eşyalarıyla birlikte gömülmesi eski Türklerin hangi inancını yansıtır?', 'Ölümden sonra hayatın devam ettiğine inanmalarını', ['Ölülerin yeniden dünyaya geleceğine inanmamalarını', 'Atların kutsal olmadığını düşünmelerini', 'Eşyaların uğursuz sayıldığını'], 'Ölünün eşyalarıyla gömülmesi, onun öbür dünyada bu eşyalara ihtiyaç duyacağı inancına, yani ahiret inancına dayanır.'),
  ('Göktürk yazıtlarında bir kişinin ölümü \'uçmağa vardı\' gibi ifadelerle anlatılır. Bu ifadedeki \'uçmak\' sözcüğü hangi anlama gelir?', 'Cennet', ['Gökyüzündeki kuşlar', 'Savaş meydanı', 'Yeraltı dünyası'], 'Eski Türkçede \'uçmak\' cennet, \'tamu\' ise cehennem anlamındadır; \'uçmağa varmak\' ölüp cennete gitmek demektir.'),
  ('Çin kaynaklarına göre Göktürk kağanının otağının kapısı genellikle hangi yöne açılırdı?', 'Doğuya', ['Batıya', 'Kuzeye', 'Güneye'], 'Göktürkler güneşin doğduğu yönü kutsal saydıklarından kağanın otağının kapısı doğuya bakardı.'),
  ('Eski Türk inancında atalara saygı gösterilmesi, ölmüş ataların ruhlarının ailesini koruduğu düşüncesine dayanır. Bu inanç biçimine ne ad verilir?', 'Atalar kültü', ['Tabiat kültü', 'Ateş kültü', 'Ay kültü'], 'Atalar kültü, ölen ataların ruhlarının yaşamayı sürdürdüğü ve soyunu koruduğu inancına dayanır.'),
  ('Eski Türk devletlerinde farklı inançlara (Budizm, Maniheizm, Hristiyanlık) mensup toplulukların bir arada yaşayabilmesi hangi özelliğin göstergesidir?', 'Dinî hoşgörünün', ['Dinî baskı ve zorlamanın', 'Tek tanrılı inancın yasaklanmasının', 'Din değiştirmenin cezalandırılmasının'], 'Türk devletleri, egemenlikleri altındaki toplulukların inançlarına genellikle karışmamış, farklı dinlerin yayılmasına izin vermiştir.'),
  ('Kahramanı çoğu araştırmacı tarafından Asya Hun hükümdarı Mete ile özdeşleştirilen Türk destanı hangisidir?', 'Oğuz Kağan Destanı', ['Ergenekon Destanı', 'Manas Destanı', 'Göç Destanı'], 'Oğuz Kağan Destanı Hun dönemine bağlanır; destandaki Oğuz Kağan\'ın fetihleri ve ordusu Mete\'nin hayatıyla benzerlik gösterir.'),
  ('Oğuz Kağan Destanı\'na göre Oğuz Kağan\'ın Gün, Ay ve Yıldız adlı büyük oğullarından türeyen boylara ne ad verilir?', 'Bozoklar', ['Üçoklar', 'İç Oğuzlar', 'Kara Türgişler'], 'Destana göre büyük oğullar buldukları altın yayı üçe bölerek paylaşmış, bu yüzden Bozok adını almışlardır. Gök, Dağ ve Deniz\'den gelenler ise Üçoklardır.'),
  ('Oğuz Kağan\'ın altı oğlunun her birinin dörder oğlu olduğu anlatılır. Destana göre bu torunlardan kaç Oğuz boyu türemiştir?', '24', ['12', '36', '18'], 'Altı oğlun her birinin dört oğlu vardır: 6 × 4 = 24. Oğuz boylarının 24 olduğu geleneği buna dayanır.'),
  ('Oğuz Kağan Destanı\'nda Oğuz Kağan\'ın ordusuna seferlerde yol gösteren hayvan hangisidir?', 'Gök yeleli bozkurt', ['Ak doğan', 'Kara boğa', 'Altın geyik'], 'Destanda gökten inen bir ışıktan çıkan gök yeleli, gök tüylü erkek kurt Oğuz Kağan\'ın ordusunun önüne düşerek ona yol gösterir.'),
  ('Ergenekon Destanı hangi Türk devletinin dönemiyle ilişkilendirilir?', 'Göktürk', ['Uygur', 'Hazar', 'Asya Hun'], 'Ergenekon Destanı Göktürklerin yenilgiden sonra kapalı bir vadiye sığınıp yüzyıllar sonra oradan çıkışını anlatır.'),
  ('Ergenekon Destanı\'na göre Türklerin kapalı vadiden çıkabilmek için yaptığı iş aşağıdakilerden hangisidir?', 'Demir dağı eritip yol açmak', ['Vadiye tünel kazmak için Çin\'den işçi getirmek', 'Gemilerle ırmak boyunca kaçmak', 'Düşmana yeniden teslim olmak'], 'Destanda bir demirci dağın demirden olduğunu fark eder; büyük ateşler yakılıp demir dağ eritilir ve dışarıya yol açılır.'),
  ('Ergenekon\'dan çıkış gününün her yıl demir dövme töreniyle kutlanması, Türk dünyasında hangi bahar bayramıyla ilişkilendirilmiştir?', 'Nevruz', ['Hıdırellez', 'Kurban Bayramı', 'Paskalya'], 'Türk geleneğinde Ergenekon\'dan çıkışın baharın başlangıcı olan Nevruz\'da gerçekleştiğine inanılır ve bu gün kutlanır.'),
  ('Göktürklerin türeyişiyle ilgili efsaneye göre düşmanlarca kolu ve bacakları kesilen bir çocuğu kurtarıp büyüten ve soyun anası sayılan hayvan hangisidir?', 'Dişi kurt', ['Ak geyik', 'Kartal', 'Boz ayı'], 'Türeyiş efsanesine göre bir dişi kurt yaralı çocuğu besleyip büyütmüş; ondan doğan on oğuldan biri Göktürk hanedanı Aşina\'nın atası olmuştur.'),
  ('İran kaynaklarında, özellikle Şehname\'de \'Afrasiyab\' adıyla anılan Türk destan kahramanı kimdir?', 'Alp Er Tonga', ['Oğuz Kağan', 'Börteçine', 'Kül Tigin'], 'Alp Er Tonga, Saka Türklerine bağlanan bir destan kahramanıdır; Firdevsi\'nin Şehname\'sinde Afrasiyab olarak geçer.'),
  ('İslamiyet öncesi Türk destanlarının ortak özelliği aşağıdakilerden hangisidir?', 'Yazarlarının belli olmaması ve uzun süre sözlü aktarılmaları', ['İlk biçimlerinin Arap harfleriyle kâğıda yazılarak oluşturulması', 'Yalnızca dinî ibadetleri ve dua metinlerini anlatmaları', 'Her birinin adı bilinen tek bir saray şairince kaleme alınması'], 'Destanlar anonimdir; toplumun ortak hafızasında oluşup kuşaktan kuşağa sözlü olarak aktarılmış, ancak sonradan yazıya geçirilmiştir.'),
  ('Doğu Göktürkler 630\'da bağımsızlıklarını kaybetmiş, İlteriş Kutluk 681\'de devleti yeniden kurmuştur. Buna göre fetret dönemi yaklaşık kaç yıl sürmüştür?', '51', ['41', '61', '71'], '681 − 630 = 51 yıl. Bu yüzden fetret dönemi çoğu kaynakta \'yarım asırlık esaret\' olarak anılır.'),
  ('Uygur Kağanlığı 744\'te kurulup 840\'ta Kırgız saldırısıyla yıkılmıştır. Devletin Ötüken\'deki egemenliği yaklaşık kaç yıl sürmüştür?', '96', ['86', '104', '106'], '840 − 744 = 96 yıl.'),
  ('Hunlar 375\'te İdil\'i geçmiş, Attila 451\'de Katalon Ovası\'nda savaşmıştır. Hunların Avrupa\'ya girişinden Katalon Savaşı\'na kadar kaç yıl geçmiştir?', '76', ['66', '86', '74'], '451 − 375 = 76 yıl. Bu süre içinde Hunlar Karadeniz\'in kuzeyinden Galya\'ya kadar ilerlemiştir.'),
  ('Aşağıdaki devletlerden hangisi Orta Asya\'da değil, Doğu Avrupa ve Karadeniz\'in kuzeyinde kurulmuştur?', 'Hazar Kağanlığı', ['Uygur Kağanlığı', 'Türgiş Kağanlığı', 'Göktürk Kağanlığı'], 'Hazar Kağanlığı Kuzey Kafkasya ve aşağı İdil bölgesinde kurulmuştur; diğerleri Orta Asya devletleridir.'),
  ('Orhun yazıtlarında Göktürklerin sıkça savaştığı ve yazıtta \'kendi milletim idi\' denilerek isyanından yakınılan boy birliği hangisidir?', 'Dokuz Oğuzlar', ['Avarlar', 'Bulgarlar', 'Peçenekler'], 'Uygurların da içinde yer aldığı Dokuz Oğuz boy birliği Göktürklere bağlıydı; isyan etmeleri üzerine Bilge Kağan döneminde birçok savaş yapılmıştır.'),
  ('Kül Tigin yazıtında Kül Tigin\'in ölüm tarihi \'koyun yılının on yedinci günü\' biçiminde verilmiştir. Bu tarihleme hangi takvim sistemine dayanır?', 'On iki hayvanlı Türk takvimi', ['Hicri takvim', 'Jülyen takvimi', 'Rumi takvim'], 'Göktürkler yılları on iki hayvan adıyla adlandıran döngüsel bir takvim kullanmıştır; koyun yılı bu döngünün yıllarından biridir.'),
  ('On iki hayvanlı takvimde \'at yılı\' olarak adlandırılan bir yıldan sonra yeniden at yılına gelinmesi için kaç yıl geçmesi gerekir?', '12', ['10', '24', '60'], 'Döngü on iki yıldan oluştuğu için aynı hayvanın adını taşıyan yıl her on iki yılda bir tekrarlanır.'),
  ('Eski Türk boylarının hayvanlarına, eşyalarına ve kimi zaman sikkelerine vurdukları, boyu ya da sahibini gösteren işarete ne ad verilir?', 'Tamga', ['Balbal', 'Tuğ', 'Yuğ'], 'Tamga, bir boyun ya da ailenin mülkiyet ve kimlik işaretidir; sürülerin ayırt edilmesinde ve resmî belgelerde mühür olarak kullanılmıştır.'),
  ('Geniş otlaklarda birbirine karışan sürülerin hangi boya ait olduğunun belirlenmesinde en çok başvurulan yöntem aşağıdakilerden hangisidir?', 'Hayvanlara vurulan boy tamgalarına bakmak', ['Hayvanların renklerini Çin yıllıklarına kaydetmek', 'Sürüleri Göktürk alfabesiyle numaralandırmak', 'Kamların kehanetlerine başvurmak'], 'Her boyun kendine özgü tamgası vardı; hayvanlara vurulan bu işaretler sahipliğin ayırt edilmesini sağlıyordu.'),
  ('Göktürk ve Uygur devletleriyle yakın ilişkiler kuran, İpek Yolu ticaretinde uzmanlaşmış ve merkezi Semerkant çevresi olan İranî topluluk hangisidir?', 'Soğdlular', ['Toharlar', 'Partlar', 'Yüeçiler'], 'Soğdlular Maveraünnehir\'de, Semerkant ve Buhara çevresinde yaşayan, İpek Yolu ticaretinde ustalaşmış bir topluluktur; Türk devletlerinde tüccar, elçi ve kâtip olarak görev almışlardır.'),
  ('Bozkır Türk devletlerinin İpek Yolu\'nu denetim altına almak istemesinin ekonomik nedeni aşağıdakilerden hangisidir?', 'Kervanlardan alınan vergi ve aracılık kazancı', ['Yolları kapatarak Çin ipeğinin değerini düşürmek', 'Kervanları yalnız askerî amaçla kullanmak', 'Ticareti tamamen yasaklayıp sürüleri korumak'], 'Yolun denetimi, geçen kervanlardan vergi almayı ve ticarete aracılık yaparak kazanç sağlamayı mümkün kılıyordu.'),
  ('Bozkırdaki Türk devletleri genellikle kısa sürede büyük bir alana yayılabilmiştir. Bunun başlıca nedeni aşağıdakilerden hangisidir?', 'Atlı orduların hızlı hareketi ve boyların kolayca yeni bir önder etrafında birleşmesi', ['Bölgede dağ ve nehir gibi doğal engellerin hiç bulunmaması', 'Komşu devletlerin hiçbir orduya sahip olmaması', 'Bozkır halklarının kalabalık kentlerde yaşayıp büyük piyade orduları beslemesi'], 'Atlı ordular geniş mesafeleri hızla aşabiliyor, bozkır boyları da güçlü bir önderin çevresinde kısa sürede toplanabiliyordu.'),
  ('Moğolistan\'daki Noin-Ula kurganlarında bulunan yün dokumalar ve keçe halılar hangi Türk devleti dönemine tarihlenir?', 'Asya Hun', ['Uygur', 'Göktürk', 'Hazar'], 'Noin-Ula kurganları Asya Hun dönemine aittir; burada bulunan halı ve dokumalar Hun maddi kültürü hakkında önemli bilgi verir.'),
  ('Çin kaynaklarına göre Göktürklerde yeni kağan, keçe üzerine oturtulup ileri gelenler tarafından havaya kaldırılarak tahta çıkarılırdı. Bu tören neyi simgeler?', 'Kağanın boy beylerince kabul edilip onaylandığını', ['Kağanın Çin imparatoruna bağlanıp ondan unvan aldığını', 'Kağanın dinî bir rahip olduğunu', 'Kağanın tahttan feragat ettiğini'], 'Keçeye oturtulup kaldırılma, beylerin yeni hükümdarı tanıdığını ve ona bağlılık sunduğunu gösteren bir tahta çıkış törenidir.'),
  ('Göktürk yazıtlarında \'il\' ve \'budun\' sözcükleri sırasıyla hangi anlamlarda kullanılır?', 'Devlet ve millet', ['Ordu ve şehir', 'Dağ ve ırmak', 'Hükümdar ve vezir'], 'Eski Türkçede \'il\' (el) devlet, \'budun\' ise millet, halk anlamındadır; yazıtlarda \'il\' ile \'budun\'un birlikteliği sık vurgulanır.'),
  ('Mançurya\'dan Macaristan ovasına kadar uzanan ve atlı göçebelerin hareketini kolaylaştıran kesintisiz otlak alanına ne ad verilir?', 'Avrasya bozkır kuşağı', ['Sahel kuşağı', 'Tayga', 'Akdeniz havzası'], 'Avrasya bozkır kuşağı doğu-batı doğrultusunda uzanan geniş bir otlaktır; Hunlardan Kumanlara kadar pek çok topluluk bu kuşak boyunca batıya göç etmiştir.'),
  ('Orta Asya\'dan Avrupa\'ya yapılan göçlerin çoğunun Hazar Denizi\'nin güneyinden değil kuzeyinden geçmesinin başlıca coğrafi nedeni nedir?', 'Kuzeyde atlılar ve sürüler için uygun açık bozkırların bulunması', ['Güneyde hiç yerleşim bulunmaması', 'Kuzeyde büyük limanların bulunması', 'Güneyin tümüyle buzullarla kaplı olup yıl boyu geçit vermemesi'], 'Hazar\'ın kuzeyi düz ve otlu bozkırlardan oluşur; güney ise dağlık ve yoğun yerleşik devletlerin bulunduğu bir alandır.'),
  ('Bir öğrenci Hun hükümdarlarının kendilerini Çin\'e yazdıkları mektuplarda \'Gök\'ün ve yerin doğurduğu, Tanrı\'nın tahta çıkardığı\' biçiminde tanıttığını okuyor. Bu ifade hangi anlayışın Hunlarda da var olduğunu gösterir?', 'Yönetme yetkisinin Tanrı\'dan geldiği inancının', ['Hükümdarın halk oylamasıyla seçildiği inancının', 'Hükümdarın Çin imparatoruna bağlı olduğunun', 'Devletin rahiplerce yönetildiğinin'], 'Bu ifade, hükümdarlığın Gök Tanrı tarafından verildiğine inanılan kut anlayışının Hunlar döneminde de var olduğunu gösterir.'),
  ('Eski Türk toplumunda otlaklar ile sürüler arasındaki mülkiyet ayrımı genellikle nasıldı?', 'Otlaklar boyun ortak kullanımında, sürüler ise ailelerin malıydı', ['Otlaklar da sürüler de yalnızca kağana aitti', 'Otlaklar ailelerin, sürüler ise devletin malıydı', 'Bozkırda mülkiyet kavramının hiç bulunmaması ve her şeyin herkese ait olması'], 'Mevsimlik otlaklar boy topluluğunun ortak kullanım alanıydı; hayvanlar ise ailelerin özel mülkü sayılır ve tamgayla işaretlenirdi.'),
  ('Eski Türklerde kağanın büyük şölenler (toy) düzenleyerek halka yemek dağıtması, hükümdarlık anlayışında hangi değere işaret eder?', 'Cömertliğin ve halkı gözetmenin meşruiyet kaynağı sayılmasına', ['Hükümdarın yalnız kendi ailesini düşünüp boy beylerini dışlamasına', 'Halkın hükümdara yemek vergisi ödemesine', 'Şölenlerin yalnızca dinî bir ibadet olmasına'], 'Toy, kağanın zenginliğini halkıyla paylaştığı bir törendir; cömertlik bozkırda iyi hükümdarın temel niteliklerinden sayılırdı.'),
  ('Eski Türk boy yapısında boyların başındaki yöneticiye genellikle hangi unvan verilirdi?', 'Bey', ['Kam', 'Bitikçi', 'Tigin'], 'Boyların başında bey bulunurdu; beyler kurultaya katılır ve savaşta boylarının askerlerine komuta ederdi.'),
  ('Orta Asya\'da kurulan ve tarihte bilinen ilk Türk devleti olarak kabul edilen devlet hangisidir?', 'Asya Hun Devleti', ['Göktürk Devleti', 'Uygur Kağanlığı', 'Hazar Kağanlığı'], 'Ders kitaplarında Asya Hun Devleti bilinen ilk Türk devleti olarak kabul edilir; Göktürk, Uygur ve Hazar devletleri daha sonra kurulmuştur.'),
  ('Aşağıdakilerden hangisi İslamiyet\'ten önce kurulmuş Türk devletlerinden biri değildir?', 'Karahanlılar', ['Göktürkler', 'Avarlar', 'Türgişler'], 'Karahanlılar İslamiyet\'i resmî din olarak kabul eden ilk Türk devletidir; diğerleri İslamiyet öncesi döneme aittir.'),
  ('Aşağıdakilerden hangisi Uygurlarla ilgili bir özellik değildir?', 'Ergenekon Destanı\'nın kahramanları olmaları', ['Maniheizmi devlet dini yapmaları', 'Ordu-Balık\'ı Orhun kıyısında başkent edinmeleri', 'Kansu ve Turfan\'da devlet kurmaları'], 'Ergenekon Destanı Göktürklere aittir; diğer seçenekler Uygurlarla ilgilidir.'),
  ('Aşağıdakilerden hangisi Avrupa Hunlarıyla ilgili değildir?', 'Orhun Vadisi\'ne yazıt dikmeleri', ['Margus Antlaşması\'nı imzalamaları', 'Kavimler Göçü\'nü başlatmaları', 'Katalon Ovası\'nda savaşmaları'], 'Orhun yazıtları II. Göktürk Devleti\'ne aittir; diğer üç olay Avrupa Hunlarıyla ilgilidir.'),
  ('Göktürk Devleti\'nin kurulduğu 552 yılı hangi yüzyılın içindedir?', '6. yüzyıl', ['5. yüzyıl', '7. yüzyıl', '4. yüzyıl'], '501–600 yılları 6. yüzyılı oluşturur; 552 bu aralıktadır.'),
  ('Attila\'nın Avrupa Hun Devleti\'ni yönettiği dönem hangi yüzyıla aittir?', '5. yüzyıl', ['4. yüzyıl', '6. yüzyıl', '7. yüzyıl'], 'Attila 434–453 yılları arasında hüküm sürmüştür; bu yıllar 5. yüzyıl içindedir.'),
  ('Bilge Kağan yazıtında kağanın söylediklerini \'ebedî taşa\' yazdırdığını belirtmesi, yazıtın dikilme amacını nasıl açıklar?', 'Öğütlerinin sonraki kuşaklarca okunup unutulmaması', ['Taşın değerli bir maden olarak saklanması', 'Yazıtın Çin imparatoruna hediye edilmesi', 'Taşın yalnızca süs amacıyla mezar alanına dikilmesi'], 'Bilge Kağan sözlerini kalıcı taşa yazdırarak Türk milletinin bu öğütleri kuşaklar boyu okumasını amaçlamıştır.'),
  ('Göçebe Türk toplulukları hakkındaki bilgilerimizin önemli bir bölümünün Çin, Bizans ve İslam kaynaklarına dayanmasının temel nedeni aşağıdakilerden hangisidir?', 'Erken dönemde Türklerin kendi yazılı kaynaklarının sınırlı olması', ['Türklerin bu ülkelerde yaşaması', 'Türkçe yazılmış eski kaynakların Çinlilerce toplatılıp yakılmış olması', 'Türklerin tarih yazmayı yasaklaması'], 'Orhun yazıtlarından önceki dönemlere ait Türkçe yazılı kaynak çok azdır; bu yüzden komşu medeniyetlerin kayıtları önemli bilgi kaynağıdır.'),
  ('Bozkırda bir ailenin zenginliği genellikle hangi ölçüyle değerlendirilirdi?', 'Sahip olduğu sürünün, özellikle at sayısının büyüklüğüyle', ['Sahip olduğu taş evlerin sayısıyla', 'Biriktirdiği altın ve gümüş sikkelerin toplam ağırlığıyla', 'Ektiği pirinç tarlalarının genişliğiyle'], 'Hayvancılığa dayalı ekonomide servet sürüdür; at hem ulaşım hem savaş aracı olduğundan en değerli varlıktı.'),
  ('Eski Türkçede \'kağan\' unvanı sonraki dönemlerde Türk-İslam devletlerinde hangi biçimde de kullanılmıştır?', 'Hakan', ['Sultan', 'Halife', 'Şah'], '\'Kağan\' sözcüğü zamanla \'hakan\' biçimini almış; Karahanlılar ve Osmanlılar da bu unvanı kullanmıştır. Sultan ve halife Arapça, şah ise Farsça kökenlidir.'),
  ('Bizans elçisi Zemarkhos\'un Göktürk ülkesine vardığında eşyalarıyla birlikte ateşlerin arasından geçirilmesi hangi inançla ilgilidir?', 'Ateşin kötü ruhları uzaklaştırıp arındırdığı inancıyla', ['Ateşe tapan bir dinin resmî olarak benimsenmesiyle', 'Elçiye yabancı olduğu için uygulanan bir ceza ve aşağılama töreniyle', 'Kış soğuğundan korunma ihtiyacıyla'], 'Menandros\'un aktardığına göre Göktürkler yabancı elçiyi ve eşyalarını ateşler arasından geçirerek kötü ruhlardan arındırmıştır.'),
  ('Çin kaynaklarına göre Göktürk kağanının ordugâhının önünde dikili duran ve devletin simgesi sayılan sancağın tepesinde hangi figür bulunurdu?', 'Altın kurt başı', ['Gümüş kartal', 'Hilal ve yıldız', 'Ejderha başı'], 'Sui ve Tang kaynakları, Göktürklerin sancaklarının tepesinde altından bir kurt başı bulunduğunu kaydeder; bu, türeyiş efsanesindeki kurtla bağlantılıdır.'),
  ('Aşağıdakilerden hangisi eski Türklerde hükümdarlık simgeleri arasında yer almaz?', 'Hırka-i saadet', ['Tuğ', 'Davul (kös) ve nevbet', 'Otağ'], 'Tuğ, davul, otağ, sancak, yay ve ok eski Türk hükümdarlık simgeleridir. Hırka-i saadet ise İslami dönemde halifelikle ilişkilendirilen kutsal bir emanettir.'),
  ('At kuyruğu ya da yak kılından yapılan ve eski Türklerde hükümdarlık ile komutanlık simgesi olarak kullanılan sancak benzeri işarete ne ad verilir?', 'Tuğ', ['Tamga', 'Balbal', 'Kurgan'], 'Tuğ, bir direğin ucuna bağlanan at ya da yak kılından yapılan bir simgedir; sayısı taşıyanın rütbesini gösterirdi.'),
  ('İkili teşkilatta doğu kanadının batı kanadından üstün sayılmasının eski Türk inançlarıyla ilişkisi nasıl açıklanır?', 'Güneşin doğduğu yönün kutsal kabul edilmesiyle', ['Doğunun denize daha yakın olmasıyla', 'Batı kanadının Çin\'e daha yakın olup tehlikeye açık bulunmasıyla', 'Doğuda hiç düşman bulunmamasıyla'], 'Eski Türkler güneşin doğduğu yönü kutsal saymış, bu yüzden kağan doğu kanadında oturmuş ve batı kanadı ona bağlı kabul edilmiştir.'),
  ('Batı Göktürk Devleti 659\'da hangi gücün saldırısıyla yıkılmıştır?', 'Tang hanedanı', ['Sasani İmparatorluğu', 'Emevi Halifeliği', 'Hazar Kağanlığı'], 'Doğu Göktürkleri 630\'da yenen Tang hanedanı, Batı Göktürk Devleti\'ne de 659\'da son vermiştir.'),
  ('Altay\'da açılan bir kurganda bir erkek iskeletinin yanında eyerli bir at, ok uçları, yay parçaları ve süslü bir kemer bulunmuştur. Bu buluntulara göre gömülen kişi hakkında en makul çıkarım hangisidir?', 'Toplumda saygın bir atlı savaşçı olduğu', ['Bir deniz tüccarı olduğu', 'Bir tapınakta görevli rahip ve din adamı olduğu', 'Yerleşik bir çiftçi olduğu'], 'At, silah ve süslü kemer, kişinin atlı bir savaşçı ve toplumda yüksek konumlu biri olduğunu gösterir.'),
  ('Bir Göktürk beyinin mezarının yanında sıra hâlinde on iki balbal bulunduğu tespit edilmiştir. Eski Türk geleneğine göre bu durum en çok neyi düşündürür?', 'Beyin savaşlarda on iki düşman öldürdüğünü', ['Beyin on iki çocuğu olduğunu', 'Beyin on iki yıl hüküm sürdüğünü', 'Mezarın sonraki dönemlerde on iki kez soyulup yeniden kapatıldığını'], 'Balbal sayısı, ölen kişinin öldürdüğü düşmanların sayısını göstermek amacıyla dikilirdi.'),
  ('Uygur, Hazar ve Kırgız gibi devlet adlarının bir boy adından gelmesi, eski Türk devletlerinin hangi özelliğini yansıtır?', 'Devletin önder bir boyun çevresinde toplanan boylar birliğine dayanmasını', ['Devletlerin yalnızca tek bir aileden oluşmasını', 'Devlet adlarının Çin sarayı tarafından verilip Türklere kabul ettirilmesini', 'Devletlerin bir şehir etrafında kurulmasını'], 'Eski Türk devletleri, güçlü bir boyun önderliğinde diğer boyların birleşmesiyle kurulmuş ve çoğu zaman önder boyun adını almıştır.'),
  ('Ergenekon Destanı\'na göre Türkler, yenilgiden sonra sığındıkları Ergenekon\'da yaklaşık ne kadar süre kalmıştır?', 'Dört yüz yıl', ['Kırk yıl', 'Yedi yıl', 'İki bin yıl'], 'Destana göre Türkler Ergenekon\'da yaklaşık dört yüz yıl yaşayıp çoğalmış, sığmayınca dışarı çıkmanın yolunu aramıştır.'),
  ('Hazarların topraklarından geçen ticaret mallarından onda bir oranında vergi aldığı bilinmektedir. Bu orana göre 3000 dirhem değerindeki bir kervan yükünden ne kadar vergi alınır?', '300 dirhem', ['30 dirhem', '3 dirhem', '1000 dirhem'], 'Onda bir, değerin yüzde onudur: 3000 ÷ 10 = 300 dirhem.'),
  ('Çin kaynaklarında Hunların yılın belirli aylarında hükümdarın sarayında toplanıp atalarına, göğe ve yere kurban sundukları anlatılır. Bu toplantıların niteliği için ne söylenebilir?', 'Dinî törenlerle siyasi kararların bir arada yürütüldüğü toplantılar oldukları', ['Yalnızca at ve ipek alım satımı için kurulan pazarlar olduğu', 'Çin imparatorunun başkanlık ettiği meclisler olduğu', 'Kadınların katılamadığı dinî ayinler olduğu'], 'Hunların büyük toplantılarında hem kurban törenleri yapılır hem de devlet işleri görüşülürdü; bu yapı sonraki kurultay geleneğinin öncülüdür.'),
  ('Turfan Uygurlarının yaşadığı Turfan bölgesi bugün hangi ülkenin sınırları içindedir?', 'Çin', ['Moğolistan', 'Kazakistan', 'Kırgızistan'], 'Turfan, bugün Çin\'in Sincan Uygur Özerk Bölgesi\'nde (Doğu Türkistan) yer alır.'),
  ('Hazar Kağanlığı\'nın başkenti İtil\'in bulunduğu İdil deltası bugün hangi ülkenin topraklarındadır?', 'Rusya', ['Ukrayna', 'Kazakistan', 'Türkmenistan'], 'İdil (Volga) Nehri Hazar Denizi\'ne Rusya\'nın Astrahan bölgesinde dökülür; İtil\'in kalıntıları bu çevrede aranır.'),
  ('I. Göktürk Devleti 552\'de kurulmuş, Doğu Göktürkler 630\'da Çin egemenliğine girmiştir. Buna göre Doğu Göktürk egemenliği kesintisiz olarak kaç yıl sürmüştür?', '78', ['68', '88', '58'], '630 − 552 = 78 yıl.'),
  ('Uygur Kağanlığı\'nın kurulduğu 744 yılı hangi yüzyıla aittir?', '8. yüzyıl', ['7. yüzyıl', '9. yüzyıl', '6. yüzyıl'], '701–800 arası 8. yüzyıldır; 744 bu aralıktadır.'),
  ('Orta Asya bozkırlarında sert bir kışın ardından otların buz tabakası altında kalması ve hayvanların aç kalıp kitlesel olarak ölmesi, göçebe toplumlar için neden büyük bir tehlikedir?', 'Geçim sürülere bağlı olduğundan kıtlığa ve göçe yol açabilmesi', ['Tarım ürünlerinin fiyatını düşürmesi', 'Kentlerin surlarını yıkıp yerleşik halkı göçe zorlaması', 'Deniz ticaretini durdurması'], 'Hayvancılığa dayanan toplumda sürülerin kırılması bir anda besin, ulaşım ve servet kaybı demektir; bu da kıtlığa ve yeni otlak arayışına neden olur.'),
  ('Bozkır atlı ordularında her askerin yanında birden fazla yedek at bulundurmasının sağladığı en önemli üstünlük nedir?', 'Uzun mesafeleri dinç atlarla hızla aşabilmek', ['Atların ticaret için satılabilmesi', 'Savaşta atların piyade gibi kullanılması', 'Atların kuşatma makinesi çekmesi'], 'Yorulan atın yerine dinç bir ata geçmek, atlı orduların günde çok uzun mesafeler kat etmesini ve beklenmedik yerlerde ortaya çıkmasını sağlardı.'),
  ('Türk minyatür sanatının bilinen ilk örneklerinin hangi Türk topluluğuna ait el yazmaları ve duvar resimlerinde görüldüğü kabul edilir?', 'Uygurlar', ['Avarlar', 'Peçenekler', 'Hazarlar'], 'Uygurların Mani ve Budist kitaplarındaki resimler ile duvar resimleri, Türk resim ve minyatür sanatının ilk örnekleri arasında sayılır.'),
  ('Aşağıdaki olaylardan hangisi 9. yüzyılda yaşanmıştır?', 'Uygur Kağanlığı\'nın Kırgızlarca yıkılması', ['Katalon Ovası Savaşı', 'Bumin\'in bağımsızlığını ilan edip İl Kağan unvanını alması', 'Mete\'nin tahta çıkması'], 'Uygurların yıkılışı 840\'tadır ve 9. yüzyıla aittir. Katalon 451 (5. yüzyıl), Bumin 552 (6. yüzyıl), Mete MÖ 209\'dur.'),
  ('Karadeniz\'in kuzeyindeki bozkırlara gelen Türk toplulukları geliş sırasına göre nasıl dizilir?', 'Hunlar – Avarlar – Peçenekler – Kumanlar', ['Kumanlar – Peçenekler – Hunlar – Avarlar', 'Avarlar – Hunlar – Kumanlar – Peçenekler', 'Hunlar – Peçenekler – Avarlar – Kumanlar'], 'Hunlar 4. yüzyılda, Avarlar 6. yüzyılın ortasında, Peçenekler 9. yüzyılın sonunda, Kumanlar ise 11. yüzyılda bölgeye gelmiştir.'),
  ('Bögü Kağan 759\'da tahta çıkmış ve 779\'da öldürülmüştür. Hükümdarlığı kaç yıl sürmüştür?', '20', ['10', '25', '30'], '779 − 759 = 20 yıl.'),
  ('Bir arkeolog Moğolistan\'da bulduğu bir mezar taşında yalnızca birkaç satırlık bir veda yazısı, ölenin ailesine ve iline seslenişini okumuştur. Bu yazıtın türü için en uygun tahmin hangisidir?', 'Kişisel bir mezar yazıtı', ['Bir devletin kuruluş tarihini anlatan anıt yazıt', 'Bir ticaret sözleşmesi', 'Bir din kitabının parçası'], 'Kısa, ölenin ağzından yazılmış veda metinleri kişisel mezar yazıtlarının tipik özelliğidir; devlet tarihi anlatan anıt yazıtlar ise uzun ve ayrıntılıdır.'),
  ('Çin kaynaklarına göre Göktürk kağanının her yıl beyleriyle birlikte atalarının çıktığına inanılan mağaraya giderek kurban sunması hangi inanç ve anlatıyla bağlantılıdır?', 'Atalara saygı ve Göktürklerin türeyiş efsanesiyle', ['Maniheizmin ışık-karanlık öğretisiyle', 'Musevilikteki hac ve kurban geleneğiyle', 'Budizmin manastır yaşamıyla'], 'Göktürk türeyiş anlatılarında soyun bir mağarada çoğaldığı anlatılır; kağanın yıllık mağara ziyareti atalar kültüyle bu efsanenin birleştiğini gösterir.'),
  ('Budizmin Göktürk ve Uygur topluluklarına ulaşmasında en etkili yol aşağıdakilerden hangisidir?', 'İpek Yolu üzerindeki tüccarlar, rahipler ve vaha şehirleri', ['Akdeniz\'den gelen Bizans misyonerleri', 'Arap fetihleri ve Halifeliğin gönderdiği vaizler', 'Kuzey Buz Denizi\'nden gelen gemiciler'], 'Budizm Hindistan\'dan Orta Asya\'ya İpek Yolu üzerindeki vaha şehirleri, tüccarlar ve gezgin rahipler aracılığıyla yayılmıştır.'),
  ('Bugün Türk dillerinin Sibirya\'dan Balkanlara, Volga boyundan Çin\'e kadar geniş bir alanda konuşulması en çok hangi tarihî sürecin sonucudur?', 'Orta Asya\'dan çeşitli yönlere yapılan yüzyıllar süren göçlerin', ['Türklerin denizaşırı sömürgeler kurmasının', 'Türkçenin Çin sarayı tarafından resmî dil yapılıp yayılmasının', 'Bu bölgelerdeki halkların Türkçeyi okulda öğrenmesinin'], 'Türk dillerinin geniş yayılışı, Orta Asya\'dan doğuya, batıya, kuzeye ve güneye yapılan göç dalgalarının uzun vadeli sonucudur.'),
  ('Bir bozkır devletinin kağanı, yaylaktan kışlağa göç ederken ordugâhını da birlikte taşımaktadır. Bu durum devlet yapısı hakkında hangi çıkarımı destekler?', 'Yönetim merkezinin hükümdarla birlikte hareket eden bir ordugâh olduğunu', ['Devletin hiçbir yönetim merkezi olmadığını', 'Kağanın her yıl kurultayca değiştirilip yerine yenisinin seçildiğini', 'Devletin denizden yönetildiğini'], 'Göçebe devletlerde başkent çoğu zaman kağanın otağının bulunduğu yerdir; hükümdar göç ettikçe yönetim de onunla birlikte taşınır.'),
  ('Asya Hunlarının Çin\'e karşı kullandığı \'ani akın ve geri çekilme\' savaş biçimine karşı Çin\'in en uzun soluklu savunma önlemi hangisi olmuştur?', 'Kuzey sınırını sur ve gözetleme kuleleriyle tahkim etmek', ['Büyük bir donanma kurup Hun kıyılarına çıkarma yapmak', 'Başkenti güneye taşıyıp kuzeyi boşaltmak', 'Hunlarla bütün ticareti serbest bırakmak'], 'Hareketli akıncılara karşı Çin, kuzey sınırını sur, kale ve gözetleme kuleleriyle tahkim ederek akınları erken fark edip durdurmaya çalışmıştır.'),
  ('Orhun yazıtlarındaki \'Tengri\', \'Türk budun\', \'kağan\', \'yer\' ve \'sub\' (su) gibi sözcüklerin bugün de anlaşılabilmesi neyi gösterir?', 'Türkçenin yüzyıllar boyunca temel söz varlığını koruduğunu', ['Yazıtların yakın zamanda yazıldığını', 'Türkçenin Çinceden türeyip zamanla ondan ayrılmış bir dil olduğunu', 'Orhun yazıtlarının Latin harfleriyle yazıldığını'], 'Yaklaşık 1300 yıllık metinlerdeki pek çok sözcüğün bugün de tanınabilmesi, Türkçenin temel söz varlığında güçlü bir süreklilik olduğunu gösterir.'),
  ('Göktürk alfabesiyle yazılmış metinlerin bulunduğu bölgeler arasında aşağıdakilerden hangisi yer almaz?', 'Kuzey Afrika', ['Moğolistan', 'Yenisey havzası', 'Doğu Türkistan'], 'Göktürk harfli metinler Moğolistan, Yenisey, Doğu Türkistan ve Talas gibi Orta Asya bölgelerinde bulunmuştur; Kuzey Afrika bu alanın dışındadır.'),
  ('Türk-İslam devletlerinden önce Orta Asya\'da yaşayan Türk topluluklarının benimsediği dinler arasında aşağıdakilerden hangisi yer almaz?', 'Şintoizm', ['Budizm', 'Maniheizm', 'Gök Tanrı inancı'], 'Gök Tanrı inancının yanında Budizm ve Maniheizm de Türkler arasında yayılmıştır. Şintoizm Japonya\'ya özgü bir inançtır.'),
  ('Eski Türklerde \'yuğ\' töreninin ardından ölen kişinin anısına taş dikilmesi ve yazıt yazılması, toplumun hangi değerine işaret eder?', 'Ölenin adını ve yaptıklarını kalıcı biçimde yaşatma isteğine', ['Ölüleri unutmayı öğütlemeye', 'Taş ticaretini geliştirip ustalara iş sağlamaya', 'Ölenin malını devlete devretmeye'], 'Mezar taşları ve yazıtlar ölenin kahramanlıklarını ve adını gelecek kuşaklara aktarmayı amaçlar; bu, eski Türklerde ad ve şan kavramının önemini gösterir.'),
  ('Bozkırdaki Türk boylarının hayvanlarını kışın beslemek için yaz aylarında ot biçip saklaması hangi sorunu önlemeye yönelikti?', 'Kar ve buzun otlakları örttüğü dönemde sürülerin aç kalmasını', ['Otların tarım ürünü olarak kentlerdeki pazarlarda satılmasını', 'Atların aşırı kilo almasını', 'Yazın otlakların sular altında kalmasını'], 'Sert kışlarda hayvanlar otlaklardan yararlanamadığından önceden hazırlanan ot, sürülerin hayatta kalması için önemliydi.'),
];
